builtin_task_spawn:
; task_spawn(ctx, stack_base, stack_words, entry): fabricate an
; initial context for a fresh task. The resume PC (entry) is
; parked at the top of the task stack region; R/P registers
; start zeroed; FP starts at stack_base; flags are inherited
; from the spawning task.
; entry stack: [ret][ctx][stack_base][stack_words][entry]
MOV P1, [SP+2]
MOV P2, [SP+4]
MOV P7, P3
MOV P3, [SP+6]
MOV P4, [SP+8]
MOV P5, P3
ADD P5, P3
ADD P5, P2
SUB P5, 2
MOV [P5+0], P4
MOV [P1+4], P5
MOV P6, 0
MOV [P1+6], P6
MOV P6, P2
MOV [P1+2], P6
PUSHF
POP P6
MOV [P1+0], P6
MOV P3, 0
MOV [P1+34], P3
MOV P6, 0
MOV [P1+28], P6
MOV [P1+30], P6
MOV [P1+32], P6
MOV [P1+36], P6
MOV [P1+38], P6
MOV [P1+40], P6
MOV [P1+42], P6
MOV R0, 0
MOV [P1+8], P6
MOV R1, 0
MOV [P1+10], P6
MOV R2, 0
MOV [P1+12], P6
MOV R3, 0
MOV [P1+14], P6
MOV R4, 0
MOV [P1+16], P6
MOV R5, 0
MOV [P1+18], P6
MOV R6, 0
MOV [P1+20], P6
MOV R7, 0
MOV [P1+22], P6
MOV R8, 0
MOV [P1+24], P6
MOV R9, 0
MOV [P1+26], P6
MOV P3, P7
MOV P5, [SP+0]
MOV [SP+8], P5
ADD SP, 8
RET
builtin_task_switch:
; task_switch(save_ctx, restore_ctx): symmetric coroutine
; switch. Saves the CURRENT task into save_ctx (flags, FP, a
; resume SP with the resume PC parked on its own stack, all R
; and P0-P7 registers) and enters the task described by
; restore_ctx via RET. On the next resume, execution continues
; right after this call, exactly as if task_switch had just
; returned. P0/P1 entering the stub hold the arg-eval scratch,
; so the save records those slots as-seen (P0-P7 are compiler
; scratch anyway; P3 -- the DIV remainder -- IS preserved).
; entry stack: [ret][save_ctx][restore_ctx]
MOV P1, [SP+2]
MOV [P1+32], P2
MOV [P1+34], P3
MOV [P1+36], P4
MOV [P1+38], P5
MOV [P1+40], P6
MOV [P1+42], P7
MOV [P1+30], P1
MOV [P1+28], P0
MOV P2, [SP+4]
; --- save phase: stage live registers through P5 ---
MOV P5, R0
MOV [P1+8], P5
MOV P5, R1
MOV [P1+10], P5
MOV P5, R2
MOV [P1+12], P5
MOV P5, R3
MOV [P1+14], P5
MOV P5, R4
MOV [P1+16], P5
MOV P5, R5
MOV [P1+18], P5
MOV P5, R6
MOV [P1+20], P5
MOV P5, R7
MOV [P1+22], P5
MOV P5, R8
MOV [P1+24], P5
MOV P5, R9
MOV [P1+26], P5
MOV P5, FP
MOV [P1+2], P5
PUSHF
POP P5
MOV [P1+0], P5
; park the resume PC on THIS task stack and record the SP that
; makes a plain RET land on it after the 2 args and the return
; address are consumed (SP+6).
MOV P5, [SP+0]
MOV [SP+4], P5
MOV P5, SP
ADD P5, 4
MOV [P1+4], P5
; --- restore phase: P2 stays the base pointer throughout; P6
; is the only scratch and is re-loaded from memory near the end
; (memory->R loads are byte loads, so R values stage via P6).
MOV P6, [P2+0]
PUSH P6
POPF
MOV P6, [P2+8]
MOV R0, P6
MOV P6, [P2+10]
MOV R1, P6
MOV P6, [P2+12]
MOV R2, P6
MOV P6, [P2+14]
MOV R3, P6
MOV P6, [P2+16]
MOV R4, P6
MOV P6, [P2+18]
MOV R5, P6
MOV P6, [P2+20]
MOV R6, P6
MOV P6, [P2+22]
MOV R7, P6
MOV P6, [P2+24]
MOV R8, P6
MOV P6, [P2+26]
MOV R9, P6
MOV P0, [P2+28]
MOV P1, [P2+30]
MOV P3, [P2+34]
MOV P4, [P2+36]
MOV P6, [P2+38]
MOV P5, P6
MOV P6, [P2+42]
MOV P7, P6
MOV P6, [P2+40]
MOV FP, [P2+2]
MOV SP, [P2+4]
MOV P2, [P2+32]
RET
